/* Live demo on the landing page: preview -> backup on invented sample files.
 * Runs only in the page memory: no network, no storage, nothing is read or written on the visitor's computer.
 * The section skeleton (#demo, title, label) is generated by tools/build_presentation.py; this file builds the controls. */
(function () {
  'use strict';
  var root = document.getElementById('demo');
  if (!root || root.getAttribute('data-demo') !== 'kaktus') return;
  var body = root.querySelector('.ppk-demo-body');
  if (!body) return;

  var lang = (document.documentElement.lang || 'de').slice(0, 2);
  var TEXT = {
    de: { from: 'Quelle', fromValue: 'Dokumente (Beispiel)', to: 'Ziel', toValue: 'Backup-Laufwerk (E:)', preview: 'Vorschau berechnen', run: 'Sicherung starten',
          hint: 'Klicken Sie auf „Vorschau berechnen“ — die App zeigt zuerst, was passieren wird.', ready: 'Vorschau fertig. Mit „Sicherung starten“ geht es weiter.',
          progress: 'Fortschritt der Sicherung', list: 'Vorschau der Dateien',
          states: { 'new': 'neu', changed: 'geändert', same: 'gleich' }, acts: { copy: 'kopieren', keep: 'alte Version behalten', skip: 'überspringen' },
          done: function (c, k, s) { return '✓ Fertig: ' + c + ' Dateien kopiert, ' + k + ' alte Versionen behalten, ' + s + ' übersprungen. (Demo — nichts wurde kopiert.)'; } },
    en: { from: 'Source', fromValue: 'Documents (sample)', to: 'Target', toValue: 'Backup drive (E:)', preview: 'Calculate preview', run: 'Start backup',
          hint: 'Click “Calculate preview” — the app first shows what will happen.', ready: 'Preview ready. Continue with “Start backup”.',
          progress: 'Backup progress', list: 'File preview',
          states: { 'new': 'new', changed: 'changed', same: 'same' }, acts: { copy: 'copy', keep: 'keep old version', skip: 'skip' },
          done: function (c, k, s) { return '✓ Done: ' + c + ' files copied, ' + k + ' old versions kept, ' + s + ' skipped. (Demo — nothing was copied.)'; } },
    ru: { from: 'Источник', fromValue: 'Документы (пример)', to: 'Назначение', toValue: 'Диск резервной копии (E:)', preview: 'Рассчитать предпросмотр', run: 'Начать копирование',
          hint: 'Нажмите «Рассчитать предпросмотр» — программа сначала покажет, что произойдёт.', ready: 'Предпросмотр готов. Продолжите кнопкой «Начать копирование».',
          progress: 'Ход копирования', list: 'Предпросмотр файлов',
          states: { 'new': 'новый', changed: 'изменён', same: 'без изменений' }, acts: { copy: 'копировать', keep: 'сохранить старую версию', skip: 'пропустить' },
          done: function (c, k, s) { return '✓ Готово: скопировано файлов — ' + c + ', сохранено старых версий — ' + k + ', пропущено — ' + s + '. (Демо — ничего не копировалось.)'; } }
  };
  var T = TEXT[lang] || TEXT.de;

  /* invented files: [name, state, action] */
  var FILES = [
    ['Bewerbung_Praktikum.pdf', 'new', 'copy'],
    ['Notizen/Woche_45.txt', 'changed', 'keep'],
    ['Fotos/Urlaub_001.jpg', 'same', 'skip'],
    ['Fotos/Urlaub_002.jpg', 'same', 'skip'],
    ['Projekte/Kartei.xlsx', 'changed', 'keep'],
    ['Rechnungen/2026-11.pdf', 'new', 'copy']
  ];
  var BADGE = { copy: ' ppk-badge-ok', keep: ' ppk-badge-warn', skip: '' };
  var reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }
  function field(label, value) {
    var f = el('div', 'ppk-field');
    f.appendChild(el('small', null, label));
    f.appendChild(document.createTextNode(value));
    return f;
  }

  /* the plant (assets/cactus-demo.js) lives in the skeleton; keep it and put it back to the right of the demo */
  var plant = body.querySelector('[data-cactus-demo]');
  body.textContent = '';
  var side = el('div', 'ppk-demo-side');
  var main = el('div', 'ppk-demo-main');
  var previewBtn = el('button', 'ppk-btn ppk-btn-primary', T.preview);
  previewBtn.type = 'button';
  var runBtn = el('button', 'ppk-btn', T.run);
  runBtn.type = 'button';
  runBtn.disabled = true;
  side.appendChild(field(T.from, T.fromValue));
  side.appendChild(field(T.to, T.toValue));
  side.appendChild(previewBtn);
  side.appendChild(runBtn);

  var rows = el('ul', 'ppk-rows');
  rows.setAttribute('aria-label', T.list);
  var bar = el('div', 'ppk-progress');
  bar.hidden = true;
  bar.setAttribute('role', 'progressbar');
  bar.setAttribute('aria-label', T.progress);
  bar.setAttribute('aria-valuemin', '0');
  bar.setAttribute('aria-valuemax', '100');
  bar.setAttribute('aria-valuenow', '0');
  var fill = el('i');
  bar.appendChild(fill);
  var msg = el('div', 'ppk-demo-empty', T.hint);
  msg.setAttribute('role', 'status');
  msg.setAttribute('aria-live', 'polite');
  msg.tabIndex = -1;
  main.appendChild(rows);
  main.appendChild(bar);
  main.appendChild(msg);
  body.appendChild(side);
  body.appendChild(main);
  if (plant) body.appendChild(plant);

  var timers = [];
  function later(fn, ms) {
    var id = setTimeout(fn, reduced ? 0 : ms);
    timers.push(id);
  }
  function cancelAll() {
    while (timers.length) clearTimeout(timers.pop());
  }

  function addRow(f) {
    var li = el('li');
    var name = el('span', null, f[0]);
    name.appendChild(el('small', null, ' · ' + T.states[f[1]]));
    li.appendChild(name);
    li.appendChild(el('span', 'ppk-badge' + BADGE[f[2]], T.acts[f[2]]));
    rows.appendChild(li);
  }

  previewBtn.addEventListener('click', function () {
    cancelAll();
    rows.textContent = '';
    bar.hidden = true;
    fill.style.width = '0%';
    runBtn.disabled = true;
    msg.className = 'ppk-demo-empty';
    msg.textContent = '';
    FILES.forEach(function (f, i) {
      later(function () {
        addRow(f);
        if (i === FILES.length - 1) {
          runBtn.disabled = false;
          msg.textContent = T.ready;
        }
      }, i * 140);
    });
  });

  runBtn.addEventListener('click', function () {
    cancelAll();
    runBtn.disabled = true;
    msg.className = 'ppk-demo-empty';
    msg.textContent = '';
    bar.hidden = false;
    var p = 0;
    function step() {
      fill.style.width = p + '%';
      bar.setAttribute('aria-valuenow', String(p));
      if (p >= 100) {
        var c = 0, k = 0, s = 0;
        FILES.forEach(function (f) { if (f[2] === 'copy') c++; else if (f[2] === 'keep') k++; else s++; });
        msg.className = 'ppk-demo-empty ppk-demo-done';
        msg.textContent = T.done(c, k, s);
        msg.focus();
        return;
      }
      p = Math.min(100, p + 5);
      later(step, 45);
    }
    step();
  });
})();
